import{_ as t,a as r}from"./chunks/ark_4_in_1_esc_with_connectors.D8MzwkVv.js";import{_ as i,o,c as a,al as l}from"./chunks/framework.7vp1BMOE.js";const f=JSON.parse('{"title":"ARK 4IN1 ESC (with/without Connectors)","description":"","frontmatter":{},"headers":[],"relativePath":"zh/esc/ark_4in1_esc.md","filePath":"zh/esc/ark_4in1_esc.md"}'),n={name:"zh/esc/ark_4in1_esc.md"};function s(c,e,h,u,p,d){return o(),a("div",null,[...e[0]||(e[0]=[l('<h1 id="ark-4in1-esc-with-without-connectors" tabindex="-1">ARK 4IN1 ESC (with/without Connectors) <a class="header-anchor" href="#ark-4in1-esc-with-without-connectors" aria-label="Permalink to &quot;ARK 4IN1 ESC (with/without Connectors)&quot;">​</a></h1><p>4 in 1 Electronic Speed Controller (ESC) that is made in the USA, NDAA compliant, and DIU Blue Framework listed.</p><p>The ESC comes in variants without connectors that you can solder in place, and a variant that has built-in motor and battery connectors (no soldering required).</p><p><img src="'+t+'" alt="ARK 4IN1 ESC without connectors "><img src="'+r+'" alt="ARK 4IN1 ESC with connectors"></p><h2 id="购买渠道" tabindex="-1">购买渠道 <a class="header-anchor" href="#购买渠道" aria-label="Permalink to &quot;购买渠道&quot;">​</a></h2><p>Order this module from:</p><ul><li><a href="https://arkelectron.com/product/ark-4in1-esc/" target="_blank" rel="noreferrer">4IN1 ESC (with connectors)</a> (ARK Electronics - US)</li><li><a href="https://arkelectron.com/product/ark-4in1-esc-cons/" target="_blank" rel="noreferrer">ARK Electronics (without connectors)</a> (ARK Electronics US)</li></ul><h2 id="hardware-specifications" tabindex="-1">Hardware Specifications <a class="header-anchor" href="#hardware-specifications" aria-label="Permalink to &quot;Hardware Specifications&quot;">​</a></h2><ul><li><p>Battery Voltage: 3-8s</p><ul><li>6V Minimum</li><li>65V Absolute Maximum</li></ul></li><li><p>Current Rating: 50A Continuous, 75A Burst Per Motor</p></li><li><p><a href="https://www.st.com/en/microcontrollers-microprocessors/stm32f0-series.html" target="_blank" rel="noreferrer">STM32F0</a></p></li><li><p><a href="https://github.com/am32-firmware/AM32/pull/27" target="_blank" rel="noreferrer">AM32 Firmware</a></p></li><li><p>Onboard Current Sensor, Serial Telemetry</p><ul><li>100V/A</li></ul></li><li><p>Input Protocols</p><ul><li>DShot (300, 600)</li><li>Bi-directional DShot</li><li>KISS Serial Telemetry</li><li>PWM</li></ul></li><li><p>8 Pin JST-SH Input/Output</p></li><li><p>10 Pin JST-SH Debug</p></li><li><p>Motor &amp; Battery Connectors (with-connector version)</p><ul><li>MR30 Connector Limit Per Motor: 30A Continuous, 40A Burst</li><li>Four MR30 Motor Connectors</li></ul></li><li><p>Dimensions (with connectors)</p><ul><li>Size: 77.00mm x 42.00mm x 9.43mm</li><li>Mounting Pattern: 30.5mm</li><li>Weight: 24g</li></ul></li><li><p>Dimensions (without connectors)</p><ul><li>Size: 43.00mm x 40.50mm x 7.60mm</li><li>Mounting Pattern: 30.5mm</li><li>Weight: 14.5g</li></ul></li></ul><p>Other</p><ul><li>Made in the USA</li><li>Open source AM32 firmware</li><li><a href="https://www.diu.mil/blue-uas/framework" target="_blank" rel="noreferrer">DIU Blue Framework Listed</a></li></ul><h2 id="px4-配置" tabindex="-1">PX4 配置 <a class="header-anchor" href="#px4-配置" aria-label="Permalink to &quot;PX4 配置&quot;">​</a></h2><p>The ARK 4IN1 ESC supports DShot 300/600, Bidirectional DShot, and PWM input protocols.</p><ul><li><strong>Bidirectional DShot</strong>: Select BDShot300 or BDShot600 in the <a href="./../config/actuators">Actuator Configuration</a> to enable eRPM telemetry.</li><li><strong><a href="https://github.com/bird-sanctuary/extended-dshot-telemetry" target="_blank" rel="noreferrer">Extended DShot Telemetry (EDT)</a></strong>: AM32 firmware supports EDT, which provides temperature, voltage, and current through the BDShot signal. Enable with <code>DSHOT_BIDIR_EDT=1</code>.</li><li><strong>AM32 EEPROM Settings</strong>: Set <code>DSHOT_ESC_TYPE=1</code> to enable reading and writing ESC firmware settings via a ground station.</li></ul><p>See <a href="./../peripherals/dshot">DShot ESCs</a> for full setup details.</p><h2 id="另见" tabindex="-1">另见 <a class="header-anchor" href="#另见" aria-label="Permalink to &quot;另见&quot;">​</a></h2><ul><li><a href="https://docs.arkelectron.com/electronic-speed-controller/ark-4in1-esc" target="_blank" rel="noreferrer">ARK 4IN1 ESC CONS</a> (ARK Docs)</li><li><a href="https://brushlesswhoop.com/dshot-and-bidirectional-dshot/" target="_blank" rel="noreferrer">DShot and Bidirectional DShot</a> (brushlesswhoop.com - General DShot reference)</li><li><a href="https://github.com/bird-sanctuary/extended-dshot-telemetry" target="_blank" rel="noreferrer">Extended DShot Telemetry (EDT) Specification</a> (bird-sanctuary)</li></ul>',17)])])}const _=i(n,[["render",s]]);export{f as __pageData,_ as default};
